#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MiniCut update patch 24: UI / UX REWRITE
========================================
Install AFTER apply_23_icons_ui_bugfix.py.

Ideas behind it: things that belong together sit together, every heading is WRITTEN (icons only help), what you are about to
choose is shown (effects, sound, media), and every input is drawn by the program so all of them look and feel the same.

Inputs (new file shared/ui.py, no stock Qt slider / spin box / combo box / check box is used any more)
  Slider, NumberField (drag sideways to change, click to type, Shift = fine, Ctrl = coarse), Dial (angles), Toggle, Dropdown,
  Segmented, TextField / TextBox, Btn (icon + word), Section (titled card), KeyDot (keyframe diamond), tabs with icon + word.
  The typing itself still uses Qt's text engine, so Thai input and IME keep working.

Properties panel
  Basic:  Position / Size (+ "Keep ratio" right next to it) / Rotation (a round knob) / Look (opacity, blend), quick buttons.
  Effects: "Add effect" opens a gallery where every effect is shown on YOUR current frame; every effect card has a live thumbnail.
  Audio:  waveform + a Listen button (plays only this clip with its effects), volume, sound effects.
  Keys:   modern motion-curve editor with a ball that moves with the curve, the properties it applies to are clear toggles.
  Mask / Text / Settings / New project / Export / Tasks all use the new inputs.
Media pool: bigger cards, move the mouse over a video to skim through it, length shown, a preview card (video: skim, sound: Listen).
Toolbar: Text and Record moved into the timeline toolbar; buttons say what they do (words drop out one by one when the window is narrow).
Nodes: no more switching pages. "Nodes" is a tab next to "Timeline", so the preview, media and properties stay visible.

Changed: app.py, shared/{widgets,icons,dialogs}.py, workspace/{actions,panels,timeline,node_editor,effects_panel,afx_panel,progress_ring,curve_panel}.py,
render/export.py, project/create.py.  New: shared/ui.py, workspace/preview_widgets.py  (originals are backed up first)

    python apply_24_ui_rewrite.py            install the update
    python apply_24_ui_rewrite.py --check    only show what would change
    python apply_24_ui_rewrite.py --revert   undo the last install
    python apply_24_ui_rewrite.py --force    install even if you edited one of these files yourself
"""

