                         '\n'
                         '# ========================================================== Dial '
                         '========================================================\n'
                         'class Dial(QWidget):\n'
                         '    """Round knob for an angle in degrees (0 = up, clockwise is positive). The value can go past a full turn."""\n'
                         '    changed = Signal(float)\n'
                         '    finished = Signal()\n'
                         '    def __init__(self, value=0.0, lo=-36000.0, hi=36000.0, size=92):\n'
                         '        super().__init__(); self.v = float(value); self.lo, self.hi = lo, hi; self._last = None; self.setFixedSize(size, '
                         'size); self.setCursor(Qt.PointingHandCursor); self.setFocusPolicy(Qt.NoFocus)\n'
                         '    def value(self): return self.v\n'
                         '    def setValue(self, v): self.v = float(v); self.update()\n'
                         '    def _ang(self, pos):\n'
                         '        c = QPointF(self.width() / 2, self.height() / 2); return math.degrees(math.atan2(pos.x() - c.x(), -(pos.y() - '
                         'c.y())))\n'
                         '    def paintEvent(self, e):\n'
                         '        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); c = pal(); w = self.width(); r = QRectF(8, 8, w - 16, '
                         'w - 16); ctr = r.center()\n'
                         '        p.setPen(QPen(QColor(c["line"]), 1)); p.setBrush(QColor(c["field"])); p.drawEllipse(r)\n'
                         '        for i in range(24):\n'
                         '            a = math.radians(i * 15); big = i % 6 == 0; r0, r1 = r.width() / 2 - (7 if big else 4), r.width() / 2 - 2\n'
                         '            p.setPen(QPen(QColor(c["dim"] if big else c["line"]), 1.4 if big else 1))\n'
                         '            p.drawLine(QPointF(ctr.x() + r0 * math.sin(a), ctr.y() - r0 * math.cos(a)), QPointF(ctr.x() + r1 * '
                         'math.sin(a), ctr.y() - r1 * math.cos(a)))\n'
                         '        a_deg = self.v % 360; arc = QRectF(r).adjusted(-4, -4, 4, 4)\n'
                         '        p.setPen(QPen(QColor(c["accent"]), 3.2, Qt.SolidLine, Qt.RoundCap)); p.drawArc(arc, 90 * 16, int(-a_deg * 16))\n'
                         '        a = math.radians(self.v); n = r.width() / 2 - 12; tip = QPointF(ctr.x() + n * math.sin(a), ctr.y() - n * '
                         'math.cos(a))\n'
                         '        p.setPen(QPen(QColor("#ffffff"), 2.4, Qt.SolidLine, Qt.RoundCap)); p.drawLine(ctr, tip); '
                         'p.setBrush(QColor("#ffffff")); p.setPen(Qt.NoPen); p.drawEllipse(ctr, 3.5, 3.5)\n'
                         '    def _move(self, pos, snap):\n'
                         '        a = self._ang(pos)\n'
                         '        if self._last is None: self._last = a; return\n'
                         '        d = (a - self._last + 180) % 360 - 180; self._last = a; nv = self.v + d\n'
                         '        if snap: nv = round(nv / 15) * 15\n'
                         '        nv = round(_clamp(nv, self.lo, self.hi), 1)\n'
                         '        if nv != self.v: self.v = nv; self.update(); self.changed.emit(nv)\n'
                         '    def mousePressEvent(self, e):\n'
                         '        if e.button() == Qt.LeftButton:\n'
                         '            self._last = None; a = self._ang(e.position()); cur = self.v % 360; d = (a - cur + 180) % 360 - 180      # '
                         'jump to where it was clicked\n'
                         '            nv = round(_clamp(self.v + d, self.lo, self.hi), 1)\n'
                         '            if e.modifiers() & Qt.ShiftModifier: nv = round(nv / 15) * 15\n'
                         '            self._last = a\n'
                         '            if nv != self.v: self.v = nv; self.update(); self.changed.emit(nv)\n'
                         '    def mouseMoveEvent(self, e):\n'
                         '        if e.buttons() & Qt.LeftButton: self._move(e.position(), bool(e.modifiers() & Qt.ShiftModifier))\n'
                         '    def mouseReleaseEvent(self, e): self._last = None; self.finished.emit()\n'
                         '    def mouseDoubleClickEvent(self, e):\n'
                         '        if self.v != 0: self.v = 0.0; self.update(); self.changed.emit(0.0); self.finished.emit()\n'
                         '\n'
                         '\n'
                         '# ========================================================= Toggle '
                         '=======================================================\n'
                         'class Toggle(QWidget):\n'
                         '    toggled = Signal(bool)\n'
                         '    def __init__(self, text="", checked=False, tip=""):\n'
                         '        super().__init__(); self.on = bool(checked); self.text = text; self.setCursor(Qt.PointingHandCursor); '
                         'self.setFocusPolicy(Qt.NoFocus); self.setFixedHeight(24)\n'
                         '        if tip: self.setToolTip(tip)\n'
                         '        fm = QFontMetrics(_font(13)); self.setMinimumWidth(40 + (min(fm.horizontalAdvance(text), 120) + 8 if text else '
                         '0))\n'
                         '        if len(text) > 18:\n'
                         '            sp = QSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred); sp.setHeightForWidth(True); '
                         'self.setSizePolicy(sp)\n'
                         '    def setLight(self): self.light = True; self.update(); return self\n'
                         '    def hasHeightForWidth(self): return bool(self.text)\n'
                         '    def heightForWidth(self, w):\n'
                         '        if not self.text: return 24\n'
                         '        return max(24, QFontMetrics(_font(13)).boundingRect(0, 0, max(40, w - 44), 10000, int(Qt.TextWordWrap), '
                         'self.text).height() + 6)\n'
                         '    def sizeHint(self): return QSize(self.minimumWidth() if len(self.text) < 18 else 300, self.heightForWidth(300) if '
                         'self.text else 24)\n'
                         '    def isChecked(self): return self.on\n'
                         '    def setChecked(self, v):\n'
                         '        v = bool(v)\n'
                         '        if v != self.on: self.on = v; self.update()\n'
                         '    def paintEvent(self, e):\n'
                         '        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); c = _p(self); cy = self.height() / 2\n'
                         '        p.setPen(Qt.NoPen); p.setBrush(QColor(c["accent"] if self.on else (c["line"] if getattr(self, "light", False) else '
                         'c["field_h"]))); p.drawRoundedRect(QRectF(1, cy - 9, 34, 18), 9, 9)\n'
                         '        p.setBrush(QColor("#06121a" if self.on else "#b9b9c4")); p.drawEllipse(QPointF(27 if self.on else 10, cy), 6.5, '
                         '6.5)\n'
                         '        if self.text: p.setPen(QColor(c["text"])); p.setFont(_font(13)); p.drawText(QRectF(44, 0, self.width() - 44, '
                         'self.height()), int(Qt.AlignVCenter | Qt.AlignLeft | Qt.TextWordWrap), self.text)\n'
                         '    def mouseReleaseEvent(self, e):\n'
                         '        if e.button() == Qt.LeftButton and self.rect().contains(e.position().toPoint()): self.on = not self.on; '
                         'self.update(); self.toggled.emit(self.on)\n'
