                                          '        os.makedirs(s["project_folder"], exist_ok=True); self._collect(); s.save(); apply_ui(self.app); '
                                          'self._applied = False; self.accept()\n'
                                          '\n'
                                          '\n'
                                          'class ShortcutDialog(AnimatedDialog):\n'
                                          '    def __init__(self, app):\n'
