                                                 '        self.media = MediaList(app); self.media.picked.connect(self.set_media)\n'
                                                 '        self.palette = NodePalette(); self.palette.itemDoubleClicked.connect(lambda it: '
                                                 'self.add_from_palette(it))\n'
                                                 '        pv = QWidget(); pl = QVBoxLayout(pv); pl.setContentsMargins(0, 0, 0, 0); pl.setSpacing(0)\n'
                                                 '        top = QWidget(); tl_ = QVBoxLayout(top); tl_.setContentsMargins(0, 0, 0, 0); '
                                                 'tl_.setSpacing(6)\n'
                                                 '        self.preview = NodePreview(); tl_.addWidget(self.preview, 1)\n'
                                                 '        tr = QHBoxLayout(); tr.setSpacing(4)\n'
                                                 '        self.prev_b = tool("", "Previous frame", lambda: app.step(-1), icon="previous")\n'
                                                 '        self.play_b = tool("", "Play / Pause (Space)", app.toggle_play, icon="play", isize=20)\n'
                                                 '        self.next_b = tool("", "Next frame", lambda: app.step(1), icon="next")\n'
                                                 '        tr.addStretch(); [tr.addWidget(b) for b in (self.prev_b, self.play_b, self.next_b)]; '
                                                 'tr.addStretch()\n'
                                                 '        for lab, z in (("Fit", None), ("100%", 1.0), ("200%", 2.0)):\n'
                                                 '            zb = QPushButton(lab); zb.setToolTip("Preview zoom"); zb.clicked.connect(lambda '
                                                 '_=False, z=z: self.preview.set_zoom(z)); tr.addWidget(zb)\n'
                                                 '        self.exp_b = tool("", "Make the preview bigger", None, True, icon="expand", isize=20); '
                                                 'self.exp_b.toggled.connect(self.set_expanded); tr.addWidget(self.exp_b)\n'
                                                 '        tl_.addLayout(tr)\n'
                                                 '        self.seek = QSlider(Qt.Horizontal); self.seek.setRange(0, 1000); '
                                                 'self.seek.setFocusPolicy(Qt.NoFocus); self.seek.valueChanged.connect(self.on_seek); '
                                                 'tl_.addWidget(self.seek)\n'
