                                                 '1)\n'
                                                 '        self.side = QSplitter(Qt.Vertical); self.side.setHandleWidth(8); '
                                                 'self.side.setChildrenCollapsible(False); self.side.addWidget(top); self.side.addWidget(bottom)\n'
                                                 '        self.side.setSizes([560, 240]); self.side.setStretchFactor(0, 1); '
                                                 'self.side.setStretchFactor(1, 0)\n'
