                                            'class PropRow(QWidget):\n'
                                            '    """One animatable value: [slider] [number you can drag or type] [keyframe diamond]. mode "num" = '
                                            'number + diamond only."""\n'
                                            '    def __init__(self, insp, name, label, lo, hi, slo, shi, dec, suffix, mode="slider", tag="", '
                                            'default=None):\n'
                                            '        super().__init__(); self.insp = insp; self.name = name; self.mode = mode\n'
                                            '        lay = QHBoxLayout(self); lay.setContentsMargins(0, 0, 0, 0); lay.setSpacing(6); '
                                            'self.setToolTip(label)\n'
                                            '        dflt = DEFAULT_PROPS.get(name, 0) if default is None else default\n'
                                            '        self.sl = Slider(slo, shi, 0, dflt, dec) if mode == "slider" else None\n'
                                            '        self.sp = NumberField(0, lo, hi, dec, suffix, "" if mode == "slider" else tag, scrub=max(0.05, '
                                            '(shi - slo) / 600.0) if dec else max(1.0, (shi - slo) / 800.0), width=84 if mode == "slider" else '
                                            'None)\n'
                                            '        self.kb = KeyDot()\n'
                                            '        if mode == "slider" and tag: t = label_w(tag); t.setFixedWidth(12); lay.addWidget(t)\n'
                                            '        if self.sl is not None: lay.addWidget(self.sl, 1)\n'
                                            '        lay.addWidget(self.sp, 0 if self.sl is not None else 1); lay.addWidget(self.kb)\n'
                                            '        if self.sl is not None: self.sl.changed.connect(self._from_slider)\n'
                                            '        self.sp.changed.connect(self._from_spin); self.kb.clicked.connect(lambda: '
                                            'insp.toggle_key(name))\n'
                                            '    def _from_slider(self, v): self.sp.setValue(v); self.insp.on_prop(self.name, v)\n'
                                            '    def _from_spin(self, v):\n'
                                            '        if self.sl is not None: self.sl.setValue(v)\n'
                                            '        self.insp.on_prop(self.name, v)\n'
                                            '    def set(self, v, on, any_):\n'
                                            '        busy = (self.sl is not None and self.sl._drag) or self.sp._press is not None or '
                                            'self.sp.ed.isVisible()\n'
                                            '        if not busy:\n'
                                            '            self.sp.setValue(v)\n'
                                            '            if self.sl is not None: self.sl.setValue(v)\n'
                                            '        self.kb.setState(on, any_)\n'
                                            '\n'
                                            '\n'
