                                              '        if (mods & Qt.AltModifier) and in_lane: self.start_marquee(x, y, True, add); return\n'
                                              '        kh = self.key_hit(x, y)\n'
                                              '        if kh: self.start_keymove(kh, x, mods); return\n'
                                              '        vhit = self.hit_vol(x, y)\n'
                                              '        if vhit:\n'
