                                              '            self.drag = {"mode": "vol", "clip": c, "top": top, "bot": bot, "before": app.begin()}\n'
                                              '            return\n'
                                              '        hit = self.hit_clip(x, y)\n'
                                              '        if hit:\n'
                                              '            # Roll edit (drag the border of two touching clips: one grows, the other shrinks) only '
                                              'when NO clip was\n'
