                                              '                         "keys": copy.deepcopy(c["props"]), "before": app.begin(), "off": self.x2t(x) '
                                              '- c["start"]}\n'
                                              '            if edge == "trim_l":\n'
                                              '                nb = neighbor_before(app.proj.clips, c["track"], c["id"], c["start"])\n'
                                              '                self.drag["nbr"] = nb\n'
                                              '                if nb is not None: self.drag["nbr0"] = {"start": nb["start"], "dur": nb["dur"], '
                                              '"inp": nb["inp"]}\n'
                                              '            elif edge == "trim_r":\n'
                                              '                nb = neighbor_after(app.proj.clips, c["track"], c["id"], c["start"] + c["dur"])\n'
                                              '                self.drag["nbr"] = nb\n'
                                              '                if nb is not None:\n'
                                              '                    self.drag["nbr0"] = {"start": nb["start"], "dur": nb["dur"], "inp": nb["inp"]}\n'
                                              '                    self.drag["nbr_keys"] = copy.deepcopy(nb["props"])\n'
                                              '        else:\n'
                                              '            self.start_marquee(x, y, in_lane, add)\n'
                                              '    def _move_core(self, e):\n'
                                              '        if not self.app.proj: return\n'
                                              '        pos = e.position(); x, y = pos.x(), pos.y(); d = self.drag; app = self.app\n'
                                              '        if not d:\n'
                                              '            hit = self.hit_clip(x, y) if x > self.HEAD and y > self.RULER else None\n'
