                                              '                elif y > lanes[-1][1] + lanes[-1][2]: self.drop_hint = "bottom"\n'
                                              '        elif m == "trim_l":\n'
                                              '            # The edge may roll the clip it touches: that one shrinks or grows by the same amount, so '
                                              'the two stay\n'
