                                              '            lo, hi = trim_l_bounds(c0, prev_snap, fps, roll)\n'
                                              '            ns = max(lo, min(requested, hi))\n'
                                              '            delta = ns - d["start"]; c["start"] = ns; c["dur"] = d["start"] + d["dur"] - ns\n'
